create table public.job_positions(id bigint generated always as identity primary key,slug text not null unique,department text not null,employment_type text not null check(employment_type in ('full-time','part-time','contract','internship')),location_fa text not null,location_en text not null,title_fa text not null,title_en text not null,summary_fa text,summary_en text,description_fa text not null,description_en text not null,requirements_fa text,requirements_en text,is_published boolean not null default false,published_at timestamptz,closes_at timestamptz,position integer not null default 0 check(position>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint job_publish_date check(not is_published or published_at is not null));
create table public.job_applications(id bigint generated always as identity primary key,tracking_code text not null unique,job_id bigint references public.job_positions(id) on delete set null,locale text not null check(locale in ('fa','en')),full_name text not null,mobile text not null,email text not null,expertise text not null,resume_url text not null,note text,consent_at timestamptz not null,status text not null default 'new' check(status in ('new','reviewing','shortlisted','interview','rejected','hired','archived')),internal_note text,reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index job_positions_public_idx on public.job_positions(department,employment_type,published_at desc) where is_published;create index job_applications_status_created_idx on public.job_applications(status,created_at desc);create index job_applications_job_idx on public.job_applications(job_id,created_at desc);
create trigger job_positions_set_updated_at before update on public.job_positions for each row execute function private.set_updated_at();create trigger job_applications_set_updated_at before update on public.job_applications for each row execute function private.set_updated_at();alter table public.job_positions enable row level security;alter table public.job_applications enable row level security;
create policy job_positions_public_read on public.job_positions for select to anon,authenticated using(is_published and published_at<=now() and (closes_at is null or closes_at>now()));create policy job_positions_staff_manage on public.job_positions for all to authenticated using((select private.has_staff_role(array['manager','admin']))) with check((select private.has_staff_role(array['manager','admin'])));
create policy job_applications_public_insert on public.job_applications for insert to anon,authenticated with check(status='new' and internal_note is null and reviewed_by is null);create policy job_applications_staff_read on public.job_applications for select to authenticated using((select private.has_staff_role(array['manager','admin'])));create policy job_applications_staff_update on public.job_applications for update to authenticated using((select private.has_staff_role(array['manager','admin']))) with check((select private.has_staff_role(array['manager','admin'])));create policy job_applications_manager_delete on public.job_applications for delete to authenticated using((select private.has_staff_role(array['manager'])));
grant select on public.job_positions to anon,authenticated;grant insert,update,delete on public.job_positions to authenticated;grant insert on public.job_applications to anon,authenticated;grant select,update,delete on public.job_applications to authenticated;grant usage,select on all sequences in schema public to anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('job-resumes','job-resumes',false,10485760,array['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
